// CertificationsPage.jsx

import React, { useState, useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { Download, FileText } from 'lucide-react';
import certificationsData from '../data/Certifications.js';

const colors = {
  purple: '#8b5cf6',
  purpleDark: '#6d28d9',
  blue: '#60a5fa',
  blueDark: '#2563eb',
  bgDark: '#0f172a',
  bgCard: '#1e293b',
  textPrimary: '#ffffff',
  textMuted: '#94a3b8',
  textTertiary: '#cbd5e1',
  border: '#334155',
  accentGlow: 'rgba(139, 92, 246, 0.5)',
  gradientBackground: 'linear-gradient(135deg, #0f172a 0%, #581c87 50%, #0f172a 100%)',
  gradientText: 'linear-gradient(90deg, #c084fc 0%, #60a5fa 50%, #c084fc 100%)',
};

const spacing = {
  xs: '8px',
  sm: '12px',
  md: '16px',
  lg: '24px',
  xl: '32px',
  xxl: '48px',
  xxxl: '64px',
};

const categories = [
  { name: 'Security', color: '#f87171' },
  { name: 'Cloud', color: '#38bdf8' },
  { name: 'Development', color: '#8b5cf6' },
  { name: 'DevOps', color: '#34d399' },
  { name: 'Data', color: '#fbbf24' },
  { name: 'Architecture', color: '#a78bfa' },
  { name: 'Other', color: '#94a3b8' },
];

export default function CertificationsPage() {
  const [selectedCert, setSelectedCert] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [highlightedConnections, setHighlightedConnections] = useState(new Set());
  const svgRef = useRef();

  const categoryGroups = {};
  certificationsData.forEach(cert => {
    if (!categoryGroups[cert.category]) {
      categoryGroups[cert.category] = [];
    }
    categoryGroups[cert.category].push(cert);
  });

  // Determine which certifications to display
  const getDisplayedCerts = () => {
    if (selectedCert) {
      return [selectedCert];
    }
    if (selectedCategory) {
      return categoryGroups[selectedCategory] || [];
    }
    return certificationsData;
  };

  const displayedCerts = getDisplayedCerts();

  // D3 Network Graph
  useEffect(() => {
    if (!svgRef.current) return;
    const width = svgRef.current.clientWidth;
    const height = 600;

    // Create nodes
    const nodes = [
      { id: 'Hubert', label: 'Hubert', type: 'center', category: 'center' },
      ...certificationsData.map(cert => ({
        id: cert.id,
        label: cert.name,
        type: 'cert',
        category: cert.category,
      })),
    ];

    // Create links
    const links = [];
    certificationsData.forEach(cert => {
      links.push({ source: 'Hubert', target: cert.id });
      cert.connections.forEach(connection => {
        if (certificationsData.find(c => c.id === connection)) {
          links.push({ source: cert.id, target: connection });
        }
      });
    });

    // Remove duplicate links
    const uniqueLinks = [];
    const linkSet = new Set();
    links.forEach(link => {
      const key = [link.source, link.target].sort().join('-');
      if (!linkSet.has(key)) {
        uniqueLinks.push(link);
        linkSet.add(key);
      }
    });

    const simulation = d3
      .forceSimulation(nodes)
      .force('link', d3.forceLink(uniqueLinks).id(d => d.id).distance(80))
      .force('charge', d3.forceManyBody().strength(-300))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(40));

    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();

    const g = svg
      .attr('width', width)
      .attr('height', height)
      .attr('viewBox', `0 0 ${width} ${height}`)
      .append('g');

    // Links
    const link = g
      .selectAll('line')
      .data(uniqueLinks)
      .enter()
      .append('line')
      .attr('stroke', colors.border)
      .attr('stroke-width', 2)
      .attr('opacity', 0.4);

    // Nodes
    const node = g
      .selectAll('g.node')
      .data(nodes)
      .enter()
      .append('g')
      .attr('class', 'node')
      .call(
        d3.drag()
          .on('start', dragStarted)
          .on('drag', dragged)
          .on('end', dragEnded)
      );

    node
      .append('circle')
      .attr('r', d => (d.type === 'center' ? 40 : 25))
      .attr('fill', d => {
        if (d.type === 'center') return colors.purple;
        const cat = categories.find(c => c.name === d.category);
        return cat ? cat.color : colors.blue;
      })
      .attr('opacity', 0.9)
      .attr('stroke', colors.textPrimary)
      .attr('stroke-width', 2)
      .style('cursor', 'pointer')
      .on('click', (e, d) => {
        if (d.type !== 'center') {
          const cert = certificationsData.find(c => c.id === d.id);
          setSelectedCert(cert);
          setSelectedCategory(null);
          const connected = new Set([d.id, ...cert.connections]);
          setHighlightedConnections(connected);
        }
      })
      .on('mouseover', (e, d) => {
        link.attr('stroke', l =>
          (l.source.id === d.id || l.target.id === d.id) ? colors.purple : colors.border
        );
      })
      .on('mouseout', () => {
        link.attr('stroke', colors.border);
      });

    node
      .append('text')
      .text(d => d.label)
      .attr('text-anchor', 'middle')
      .attr('dy', '0.3em')
      .attr('fill', colors.textPrimary)
      .attr('font-size', '12px')
      .attr('font-weight', 'bold')
      .attr('pointer-events', 'none');

    function dragStarted(e, d) {
      if (!e.active) simulation.alphaTarget(0.3).restart();
      d.fx = d.x;
      d.fy = d.y;
    }

    function dragged(e, d) {
      d.fx = e.x;
      d.fy = e.y;
    }

    function dragEnded(e, d) {
      if (!e.active) simulation.alphaTarget(0);
      d.fx = null;
      d.fy = null;
    }

    simulation.on('tick', () => {
      link
        .attr('x1', d => d.source.x)
        .attr('y1', d => d.source.y)
        .attr('x2', d => d.target.x)
        .attr('y2', d => d.target.y);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    return () => simulation.stop();
  }, []);

  const handleCategoryClick = (categoryName) => {
    setSelectedCategory(selectedCategory === categoryName ? null : categoryName);
    setSelectedCert(null);
  };

  const handleClearFilters = () => {
    setSelectedCert(null);
    setSelectedCategory(null);
    setHighlightedConnections(new Set());
  };

  return (
    <div style={styles.container}>
      {/* Hero Section */}
      <section style={styles.heroSection}>
        <h1 style={styles.title}>My Certifications</h1>
        <p style={styles.introduction}>
          A collection of certifications that validate my expertise across various domains. 
          Each certification represents dedicated learning and hands-on experience in its respective field. 
          Click on any card to view or download the certification document.
        </p>
      </section>

      {/* Category Overview */}
      <section style={styles.categorySection}>
        <h2 style={styles.sectionTitle}>Certification Categories</h2>
        <div style={styles.categoryGrid}>
          {categories.map(cat => {
            const certCount = certificationsData.filter(c => c.category === cat.name).length;
            const isActive = selectedCategory === cat.name;
            return (
              <div 
                key={cat.name} 
                style={{
                  ...styles.categoryCard,
                  ...(isActive ? styles.categoryCardActive : {}),
                }}
                onClick={() => handleCategoryClick(cat.name)}
              >
                <div style={{ ...styles.categoryDot, backgroundColor: cat.color }} />
                <h3 style={styles.categoryName}>{cat.name}</h3>
                <p style={styles.skillCount}>{certCount} certification{certCount !== 1 ? 's' : ''}</p>
              </div>
            );
          })}
        </div>
        {(selectedCert || selectedCategory) && (
          <div style={styles.filterInfo}>
            <p style={styles.filterText}>
              {selectedCert 
                ? `Showing: ${selectedCert.name}` 
                : `Showing ${displayedCerts.length} certification(s) from ${selectedCategory}`}
            </p>
            <button 
              onClick={handleClearFilters}
              style={styles.clearButton}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = colors.purple;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = `rgba(139, 92, 246, 0.2)`;
              }}
            >
              Clear Filters
            </button>
          </div>
        )}
      </section>

      {/* Network Graph */}
      <section style={styles.networkSection}>
        <h2 style={styles.sectionTitle}>Certifications Network Map</h2>
        <p style={styles.networkDescription}>
          Interactive map of how my certifications connect and relate. Click on any certification bubble to highlight its connections.
        </p>
        <div style={styles.networkContainer}>
          <svg ref={svgRef} style={styles.svg} />
        </div>
        <div style={styles.networkLegend}>
          <p style={styles.legendTitle}>Click on any certification to explore its connections. Drag to reposition.</p>
          {selectedCert && (
            <div style={styles.selectedCertInfo}>
              <strong>Selected: {selectedCert.name}</strong>
              <p>Connections: {selectedCert.connections.map(id => certificationsData.find(c => c.id === id)?.name).join(', ') || 'None'}</p>
            </div>
          )}
        </div>
      </section>

      {/* Certifications Detail Cards */}
      <section style={styles.certificationsSection}>
        <h2 style={styles.sectionTitle}>
          {selectedCert 
            ? `${selectedCert.name}` 
            : selectedCategory 
            ? `${selectedCategory} Certifications` 
            : 'All Certifications'}
        </h2>
        <div style={styles.certificationsContainer}>
          {displayedCerts.map(cert => (
            <div 
              key={cert.id} 
              style={{
                ...styles.certCard,
                ...(selectedCert?.id === cert.id ? styles.certCardActive : {}),
              }}
              onClick={() => {
                setSelectedCert(cert);
                setSelectedCategory(null);
                const connected = new Set([cert.id, ...cert.connections]);
                setHighlightedConnections(connected);
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-8px)';
                e.currentTarget.style.boxShadow = `0 20px 25px -5px ${colors.accentGlow}`;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = 'none';
              }}
            >
              <div style={styles.certCardHeader}>
                <div 
                  style={{
                    ...styles.categoryBadge,
                    backgroundColor: categories.find(c => c.name === cert.category)?.color || colors.blue,
                  }}
                >
                  {cert.category}
                </div>
                <span style={styles.certDate}>{cert.obtained}</span>
              </div>

              <a
                href={cert.document}
                download={cert.document}
                style={styles.downloadButton}
                onClick={(e) => e.stopPropagation()}
                onMouseEnter={(e) => {
                e.currentTarget.style.transform = "scale(1.05)";
                e.currentTarget.style.boxShadow = `0 10px 15px -3px ${colors.accentGlow}`;
                }}
                onMouseLeave={(e) => {
                e.currentTarget.style.transform = "scale(1)";
                e.currentTarget.style.boxShadow = "none";
                }}
                >

                <div style={styles.documentContainer}>
                <div style={styles.documentIcon}>
                  <FileText size={48} color={colors.purple} />
                </div>
                <p style={styles.documentName}>{cert.name}</p>
                <p style={styles.documentHint}>PDF Certificate</p>
                </div>
              </a>     

              <h3 style={styles.certName}>{cert.name}</h3>

              <p style={styles.certSummary}>{cert.summary}</p>



              {cert.connections.length > 0 && (
                <div style={styles.connectionsContainer}>
                  <p style={styles.certLabel}>Related Certifications:</p>
                  <div style={styles.connectionsTags}>
                    {cert.connections.map(connId => {
                      const connCert = certificationsData.find(c => c.id === connId);
                      return (
                        <span key={connId} style={styles.connectionTag}>
                          {connCert?.name}
                        </span>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

